import React, { useEffect, useState } from "react";
import "./FinalProduct.css";

const FinalProduct = () => {
  const [productId, setProductId] = useState("");
  const [price, setPrice] = useState("");
  const [productName, setProductName] = useState("");
  const [category, setCategory] = useState("Electronics");
  const [loaded, setLoaded] = useState(false); // every key press reload solved
  const [products, setProducts] = useState({});

  const productIdHandler = (event) => {
    setProductId(event.target.value);  
  };
  const priceHandler = (event) => {
    setPrice(event.target.value);
  };
  const productNameHandler = (event) => {
    setProductName(event.target.value);
  };
  const categoryHandler = (event) => {
    setCategory(event.target.value);
  };

  useEffect(() => {  
    if(!loaded) {
    loadStoredData();
    setLoaded(true);
    }    
  }, [loaded]);

  const submitForm = (event) => {
    event.preventDefault();
    // const productsId = event.target.productid.value;  
    // const priceOfProduct = event.target.price.value;
    // const productName = event.target.pname.value;
    // const productCategory = event.target.categorys.value;

    const obj = {
      productId,
      price,
      productName,
      category,
    };
    localStorage.setItem(obj.productId, JSON.stringify(obj));
    
    showUserOnScreen(obj);
     setProductId('');
     setPrice('');
     setProductName('');
     setCategory('Electronics'); // i added this problem solved  here
   // showUserOnScreen(obj);
  };

  function showUserOnScreen(obj) {
    if (obj.category === "Electronics") {
      const parentEl = document.getElementById("category1");
      const childEl = document.createElement("li");
      childEl.textContent = `${obj.productId}-${obj.price}-${obj.productName}-${obj.category}`;
      parentEl.appendChild(childEl);

      const deleteButton = document.createElement("input");
      deleteButton.type = "button";
      deleteButton.value = "Delete Product";
      childEl.appendChild(deleteButton);
      parentEl.appendChild(childEl);
      deleteButton.onclick = () => {
        localStorage.removeItem(obj.productId);
        parentEl.removeChild(childEl);
      };
    }
    if (obj.category === "Food") {
      const parentEl = document.getElementById("category2");
      const childEl = document.createElement("li");
      childEl.textContent = `${obj.productId}-${obj.price}-${obj.productName}-${obj.category}`;
      parentEl.appendChild(childEl);

      const deleteButton = document.createElement("input");
      deleteButton.type = "button";
      deleteButton.value = "Delete Product";
      childEl.appendChild(deleteButton);
      parentEl.appendChild(childEl);
      deleteButton.onclick = () => {
        localStorage.removeItem(obj.productId);
        parentEl.removeChild(childEl);
      };
    }
    if (obj.category === "skinCare") {
      const parentEl = document.getElementById("category3");
      const childEl = document.createElement("li");
      childEl.textContent = `${obj.productId}-${obj.price}-${obj.productName}-${obj.category}`;
      parentEl.appendChild(childEl);

      const deleteButton = document.createElement("input");
      deleteButton.type = "button";
      deleteButton.value = "Delete Product";
      childEl.appendChild(deleteButton);
      parentEl.appendChild(childEl);
      deleteButton.onclick = () => {
        localStorage.removeItem(obj.productId);
        parentEl.removeChild(childEl);
      };
    }
  }

  function loadStoredData() {
    const storedProducts = {};
    const displayedCategories = {};
  

    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      const storedValue = localStorage.getItem(key);
      const parseValue = JSON.parse(storedValue);
     // console.log(parseValue);
     storedProducts[key] = parseValue;
      //showUserOnScreen(parseValue);
    

      // Display category heading if not already displayed
      if (!displayedCategories[parseValue.category]) {
        displayedCategories[parseValue.category] = true;
        showCategoryHeading(parseValue.category);
      }
  
      showUserOnScreen(parseValue);
    }
  
    setProducts(storedProducts); // Update state with stored products
    }
  // Update state with stored products

  
   
   
 // }
  //   window.addEventListener("DOMContentLoaded",()=>{
  //     loadStoredData();
  //  });
  return (
    <div className="container">
      <form onSubmit={submitForm}>
        <div>
          <label htmlFor="productid">Product ID:</label>
          <input
            type="number"
            id="productid"
            name="productid"
            value={productId}
            onChange={productIdHandler}
          ></input>
        </div>
        <div>
          <label htmlFor="price">Selling Price :</label>
          <input
            type="number"
            name="price"
            id="price"
            value={price}
            onChange={priceHandler}
          ></input>
        </div>
        <div>
          <label htmlFor="pname">Product Name :</label>
          <input
            type="text"
            name="pname"
            id="pname"
            value={productName}
            onChange={productNameHandler}
          ></input>
        </div>
        <div>
          <label htmlFor="category">Choose a Category:</label>
          <select name="categorys" value={category} onChange={categoryHandler}>
            <option>Electronics</option>
            <option>Food</option>

            <option>skinCare</option>
          </select>
        </div>
        <div>
          <button type="submit">Add Product</button>
        </div>
      </form>

      <div id="productsitems">
        <h1>Products</h1>
        <ul id="items"></ul>
      </div>
      <div id="category1">
        <h2>Electronics Items</h2>
      </div>
      <div id="category2">
        <h2>Food Items </h2>
      </div>
      <div id="category3">
        <h2>Skin Care Items</h2>
      </div>
    </div>
  );
};
export default FinalProduct;
